const cfg = $('Set - Config').first().json;
const response = $input.first().json;

const statusCode = response.statusCode ?? response.status ?? (response.error ? 0 : 200);
const errorMessage = response.error?.message || response.message || null;
const isHealthy = !errorMessage && statusCode === cfg.expectedStatusCode;

return [{
  json: {
    ...cfg,
    isHealthy,
    observedStatusCode: statusCode,
    healthCheckError: errorMessage,
    responseBodySnippet: JSON.stringify(response.body || response.data || '').slice(0, 500)
  }
}];

const ctx = $('IF - Is Unhealthy').first().json;
const commitsResult = $('HTTP Request - GitHub: Get Recent Commits').first().json;
const ciResult = $input.first().json;

const commits = Array.isArray(commitsResult) ? commitsResult : [];
const ciRuns = ciResult.workflow_runs || [];

// Pull filenames touched by the most recent commit(s). GitHub's list-commits endpoint doesn't
// include files by default, so we just carry commit shas forward; the file list itself is
// resolved conservatively here from commit messages/paths if present, else falls back to a
// sensible default set the team should adjust in Set - Config.
const recentCommitShas = commits.slice(0, 3).map(c => c.sha);
const recentCommitMessages = commits.slice(0, 5).map(c => ({ sha: c.sha, message: c.commit?.message, author: c.commit?.author?.name, date: c.commit?.author?.date }));

const latestCiRun = ciRuns[0] || null;
const ciFailed = latestCiRun ? latestCiRun.conclusion === 'failure' : false;

// Default candidate files - customize in Set - Config or extend this logic to call
// GET /repos/{owner}/{repo}/commits/{sha} per commit for a precise files[] list.
const candidateFiles = ['server.js', 'index.js', 'src/app.js', 'src/server.ts', 'src/index.ts'].slice(0, ctx.maxDiagnosticFilesToFetch);

return [{
  json: {
    ...ctx,
    recentCommitShas,
    recentCommitMessages,
    latestCiRunConclusion: latestCiRun?.conclusion || 'unknown',
    ciFailed,
    candidateFiles
  }
}];

const ctx = $('JS - Identify Likely Changed Files').first().json;
const aggregated = $input.first().json;
const rawFiles = aggregated.data || [];

const files = rawFiles.map(f => {
  let content = '';
  try {
    content = f.content ? Buffer.from(f.content, 'base64').toString('utf-8') : '';
  } catch (e) {
    content = '';
  }
  return { path: f.path, sha: f.sha, content: content.slice(0, 6000) };
}).filter(f => f.content);

return [{
  json: {
    ...ctx,
    fetchedFiles: files
  }
}];

const ctx = $('JS - Build Diagnosis Context').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { diagnosis: {}, prTitle: '', prDescription: '', fileChanges: [] };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { diagnosis: { rootCause: 'unknown', confidence: 'low', evidence: 'Failed to parse AI response' }, prTitle: 'Self-heal: investigate outage', prDescription: 'AI diagnosis could not be parsed automatically.', fileChanges: [], parseError: true };
}

// Merge shas back in so the commit step can update the right blob
const filesByPath = Object.fromEntries((ctx.fetchedFiles || []).map(f => [f.path, f.sha]));
const fileChanges = (parsed.fileChanges || []).map(fc => ({
  ...fc,
  sha: filesByPath[fc.path] || null
})).filter(fc => fc.sha);

return [{
  json: {
    ...ctx,
    rootCause: parsed.diagnosis?.rootCause || 'unknown',
    confidence: parsed.diagnosis?.confidence || 'low',
    evidence: parsed.diagnosis?.evidence || '',
    prTitle: parsed.prTitle || 'Self-heal: proposed fix',
    prDescription: parsed.prDescription || '',
    fileChanges,
    hasFix: fileChanges.length > 0
  }
}];
